svg.script:
//!export-start
let _pn_value = 0;
let _pn_min = 0;
let _pn_max = 100;
let _ps_unit = '';
let _pn_points = 60;
let _pn_interval = 1;
let _pb_hasSetpoint = false;
let _pn_setpoint = 0;
let _pb_off = false;
//!export-end

var __busyUntil = 0;

function toBool(v) {
    if (v === true || v === 1) return true;
    var s = String(v).toLowerCase();
    return s === 'true' || s === '1' || s === 'on';
}

function toNum(v) {
    if (v === true || v === 'true') return 1;
    if (v === false || v === 'false') return 0;
    var n = parseFloat(v);
    return isNaN(n) ? 0 : n;
}

var __points = [];
var __hasValue = false;
var __lastSample = 0;
function pushPoint(v) {
    var d = new Date();
    var label = ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2) + ':' + ('0' + d.getSeconds()).slice(-2);
    __points.push({ label: label, value: toNum(v) });
    var n = Math.max(2, Math.round(toNum(_pn_points)) || 60);
    while (__points.length > n) { __points.shift(); }
    __lastSample = Date.now();
}
function chartData() {
    return __points.length === 1 ? [__points[0], { label: __points[0].label, value: __points[0].value }] : __points.slice();
}
function sampleTick() {
    if (!__hasValue) return;
    var every = Math.max(0.2, toNum(_pn_interval) || 1) * 1000;
    if (Date.now() - __lastSample >= every) { pushPoint(_pn_value); apply(); }
}
// stop when the widget leaves the page (page change, editor), as the FUXA widget guide requires
var __sampler = setInterval(function () {
    if (!document.getElementById('ob_root')) { clearInterval(__sampler); return; }
    sampleTick();
}, 200);

function apply() {
    var preview = document.getElementById('ob_preview');
    if (preview && preview.parentNode) { preview.parentNode.removeChild(preview); }
    var el = document.getElementById('ob_el');
    if (!el) return;
    el.value = toNum(_pn_value);
    el.minValue = toNum(_pn_min);
    el.maxValue = toNum(_pn_max);
    el.unit = String(_ps_unit);
    el.data = chartData();
    el.setpoint = toBool(_pb_hasSetpoint) ? toNum(_pn_setpoint) : undefined;
    el.state = toBool(_pb_off) ? 'off' : 'active';
}

function putValue(id, value) {
    if (id === '_pn_value') { _pn_value = toNum(value); if (!__hasValue) { __hasValue = true; pushPoint(_pn_value); } }
    if (id === '_pn_min') { _pn_min = toNum(value); }
    if (id === '_pn_max') { _pn_max = toNum(value); }
    if (id === '_ps_unit') { _ps_unit = String(value); }
    if (id === '_pn_points') { _pn_points = toNum(value); }
    if (id === '_pn_interval') { _pn_interval = toNum(value); }
    if (id === '_pb_hasSetpoint') { _pb_hasSetpoint = toBool(value); }
    if (id === '_pn_setpoint') { _pn_setpoint = toNum(value); }
    if (id === '_pb_off') { _pb_off = toBool(value); }
    if (id === '__series' && value && value.forEach) { __points = []; value.forEach(function (v) { pushPoint(v); }); __hasValue = true; }
    apply();
}

function postValue(id, value) {
    // replaced at runtime: writes value to the tag bound to "id"
}

function fitBox() {
    var root = document.getElementById('ob_root');
    var fo = document.getElementById('ob_fo');
    var el = document.getElementById('ob_el');
    if (!root || !fo || !el) return;
    var w = parseFloat(root.getAttribute('width')) || 288;
    var h = parseFloat(root.getAttribute('height')) || 192;
    if (root.getAttribute('viewBox') !== '0 0 ' + w + ' ' + h) {
        root.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    }
    fo.setAttribute('width', w);
    fo.setAttribute('height', h);
    el.style.width = w + 'px';
    el.style.height = h + 'px';
    el.width = w; el.height = h;
}

(function () {
    var root = document.getElementById('ob_root');
    fitBox();
    if (root && window.MutationObserver) {
        new MutationObserver(fitBox).observe(root, { attributes: true, attributeFilter: ['width', 'height'] });
    }
})();

apply();
